// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // admin is the deployer (this test contract); call setOwner with fuzzed new owner
        vm.prank(address(this));
        bool success = c.setOwner(newOwner);

        // general rule: every successful setOwner call reports success == true
        assertTrue(success && c.owner() == newOwner);
    }
}
